// Attractor_19.0

let N = 8000 ; let M = 20 ; let RR = 300 ; let H = 20 ;
let X ; let Y ; let R ; let A ; let I ; let II ; let Q ; 

function setup(){
  createCanvas(600, 600) ; background(0) ; fill(0,0,0,10) ; 
}//setup()

function draw(){
  stroke(0) ; rect(0,0,599,599) ;
	for ( II = 0 ; II < N ; II++ ){
		X = random(-RR,+RR) ; Y = random(-RR,+RR) ;
		stroke(sin(Y/H)*125+125,0,cos(Y/H)*125+125) ;
    for ( I = 0 ; I < M ; I++ ){
      Y = (Y/2) + (RR/2) ;
      R = sqrt(pow(X,2)+pow(Y,2)) ; 
      A = atan(Y/X) ;
      if ( X < 0 ){ A = A+PI ; }  
      A = A*2 + Q ;
      X = R*cos(A) ; Y = R*sin(A) ;
    }//I
		point(X+300,Y+300) ; 
	}//let Q = 2*PI*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/600 ;
}//draw()

